from pathlib import Path
for root in ['experiments/e4','experiments/e7']:
 print('\n',root)
 for p in Path(root).glob('*'):
  if p.suffix in ('.md','.txt','.py'):
   t=p.read_text(errors='ignore')
   if any(x in t.lower() for x in ['resonance','degree-zero','degree zero','l=0']):
    print(p.name)
    lines=t.splitlines()
    for i,l in enumerate(lines):
     if any(x in l.lower() for x in ['resonance','degree-zero','degree zero','l=0']):
      print('\n'.join(lines[max(0,i-2):i+5])[:1700])

